import java.util.ArrayList;
import java.util.HashMap;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import sailpoint.object.Identity;
import sailpoint.object.QueryOptions;
import sailpoint.object.Rule;

Rule provision = context.getObjectByName(Rule.class, "LDAP ApacheDS - Provision Account");
if (provision == null) {
    return "ERROR: rule 'LDAP ApacheDS - Provision Account' not found";
}

// Read the names first, then provision (keeps the search cursor simple)
List names = new ArrayList();
Iterator it = context.search(Identity.class, new QueryOptions(), "name");
while (it.hasNext()) {
    Object[] row = (Object[]) it.next();
    names.add(row[0]);
}

StringBuilder report = new StringBuilder();
int created = 0;
for (Object n : names) {
    Map args = new HashMap();
    args.put("identityName", n);
    Object result = context.runRule(provision, args);
    String line = String.valueOf(result);
    if (line.startsWith("CREATED")) created++;
    if (!line.startsWith("SKIPPED")) report.append(line).append("\n");
    context.decache();
}
report.append("Done. Accounts created: ").append(created);
return report.toString();
